values ('bbbb0003-0000-4000-8000-000000000006', 'en', null, 'Principles of Macroeconomics', 'A first tour of how a whole economy works — measuring output, jobs and prices, growth, money, and the policies that steer it all. Structure adapted from OpenStax Principles of Macroeconomics 2e (CC BY 4.0).', null, 'foundations', 6, true, 'business', '{bbbb0003-0000-4000-8000-000000000002}')
