insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000006', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Gross domestic product (GDP) measures…","options":["the total money in circulation","the market value of final goods and services produced in a country in a period","government spending only","a country''s total wealth"],"answer":1,"explanation":"GDP is a flow: the value of final output produced within a period — see ''The Macroeconomic Perspective''."},{"prompt":"The unemployment rate is the number of unemployed divided by the…","options":["total population","adult population","labor force","number of employed"],"answer":2,"explanation":"Labor force = employed + unemployed (those without work who are looking) — see ''Unemployment''."},{"prompt":"Inflation is best described as…","options":["a one-time price jump for one good","a sustained rise in the general price level","any increase in wages","a fall in GDP"],"answer":1,"explanation":"Inflation is a general, ongoing rise in prices — see ''Inflation''."},{"prompt":"The aggregate demand curve slopes…","options":["upward, like a firm''s supply curve","downward: lower price level, more real output demanded","vertically","horizontally"],"answer":1,"explanation":"AD slopes down for the whole economy — see ''The AD/AS Model''."},{"prompt":"Economic growth is usually measured as the increase in…","options":["nominal GDP","the money supply","real GDP (adjusted for inflation)","the stock market"],"answer":2,"explanation":"Real GDP strips out price changes — see ''Economic Growth''."},{"prompt":"Which is NOT one of the three functions of money?","options":["medium of exchange","store of value","unit of account","source of interest income"],"answer":3,"explanation":"The three functions are medium of exchange, store of value, unit of account — see ''Money and Banking''."},{"prompt":"Monetary policy in most countries is carried out by the…","options":["legislature","central bank","treasury/tax authority","commercial banks"],"answer":1,"explanation":"Central banks (e.g. the Fed) set monetary policy — see ''Monetary Policy''."},{"prompt":"Fiscal policy refers to government use of…","options":["interest rates and reserves","spending and taxation","exchange rates","the reserve requirement"],"answer":1,"explanation":"Fiscal policy = government spending and taxes — see ''Government Budgets and Fiscal Policy''."}]}'::jsonb, null, 10),
  (2, 'GDP: measuring the whole economy', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute GDP from its spending components and convert nominal GDP to real GDP. Warm-up: from the diagnostic, is GDP a stock (an amount that exists) or a flow (produced over a period)?"},{"heading":"The idea","text":"GDP is the market value of all *final* goods and services produced inside a country over a period. By the expenditure approach we add four kinds of spending: consumption (C), investment (I), government purchases (G), and net exports, exports minus imports (X − M). We count only *final* goods — the flour a bakery buys is ''intermediate'' and is already inside the price of the bread, so counting both would double-count. *Nominal* GDP is measured in current prices; *real* GDP uses constant prices so a rise reflects more output, not just higher prices. The bridge between them is the GDP deflator: real GDP = nominal GDP ÷ (deflator ÷ 100)."},{"heading":"Worked example","text":"Suppose C = $14T, I = $3T, G = $4T, exports X = $2T, imports M = $3T. Net exports = 2 − 3 = −$1T. GDP = 14 + 3 + 4 + (−1) = $20T. Now convert: if nominal GDP is $22T and the GDP deflator is 110, then real GDP = 22 ÷ (110 ÷ 100) = 22 ÷ 1.10 = $20T. Prices, not extra output, explain the $2T gap between nominal and real."},{"heading":"Your turn","text":"(1) C = $10T, I = $2T, G = $3T, X = $1T, M = $2T — find GDP. (2) Are the wages a car factory pays counted separately from the cars it sells? (3) Nominal GDP = $12T, deflator = 120 — find real GDP. (4) If net exports are negative, is the country importing or exporting more? Answers: (1) 10+2+3+(1−2) = $14T; (2) no — wages are part of the cars'' value, counting both double-counts; (3) 12 ÷ 1.20 = $10T; (4) importing more."},{"heading":"Common mistakes & exit ticket","text":"Mistake: adding imports to GDP — imports are *subtracted* because they are produced abroad. Mistake: treating a rise in nominal GDP as real growth when prices rose. Exit: (a) In C+I+G+(X−M), what does the minus sign do? (b) Which GDP figure removes inflation? Answers: it subtracts imports (spending on foreign output); real GDP."}]}'::jsonb, 'GDP = C + I + G + (X − M). ''Final'' goods only — never count the same value twice.', 13),
  (3, 'Unemployment and inflation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Calculate the unemployment rate, the labor-force participation rate, and an inflation rate from a price index. Warm-up: a retiree who is not looking for work — are they ''unemployed''?"},{"heading":"The idea","text":"The *labor force* is the employed plus the unemployed, where ''unemployed'' means without a job *and* actively looking. People who are not looking (students, retirees, discouraged workers) are ''not in the labor force''. Unemployment rate = unemployed ÷ labor force × 100. The *labor-force participation rate* = labor force ÷ adult population × 100. *Inflation* is measured with a price index such as the Consumer Price Index (CPI): the inflation rate between two years = (CPI_new − CPI_old) ÷ CPI_old × 100."},{"heading":"Worked example","text":"An economy has 150 million employed and 10 million unemployed, in an adult population of 250 million. Labor force = 150 + 10 = 160 million. Unemployment rate = 10 ÷ 160 × 100 = 6.25%. Participation rate = 160 ÷ 250 × 100 = 64%. For prices, if the CPI rises from 200 to 210, inflation = (210 − 200) ÷ 200 × 100 = 5%."},{"heading":"Your turn","text":"(1) 90 million employed, 10 million unemployed — find the unemployment rate. (2) With an adult population of 125 million and that same 100-million labor force, find the participation rate. (3) CPI goes 250 → 260; find inflation. (4) A discouraged worker stops job-hunting — does the measured unemployment rate rise or fall? Answers: (1) 10 ÷ 100 × 100 = 10%; (2) 100 ÷ 125 × 100 = 80%; (3) (260−250)/250 × 100 = 4%; (4) it falls — they leave the labor force, shrinking the numerator and denominator."},{"heading":"Common mistakes & exit ticket","text":"Mistake: dividing the unemployed by the whole population instead of the labor force. Mistake: confusing the price *level* (the index) with the *inflation rate* (its percentage change). Exit: (a) Who is in the labor force but not employed? (b) CPI 100 → 103 means what inflation rate? Answers: the unemployed who are actively looking; 3%."}]}'::jsonb, 'Unemployment rate = unemployed ÷ labor force. Only job-seekers count as ''unemployed''.', 13),
  (4, 'Economic growth and living standards', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute a real GDP growth rate, estimate doubling time with the rule of 70, and find GDP per capita. Warm-up: why do we track *real* GDP per person, not just total nominal GDP?"},{"heading":"The idea","text":"Economic growth is the percentage increase in *real* GDP: growth rate = (GDP_new − GDP_old) ÷ GDP_old × 100. Small differences compound: the *rule of 70* says a quantity growing at g% per year doubles in about 70 ÷ g years. Living standards track *real GDP per capita* = real GDP ÷ population, and over the long run per-capita income rises mainly through *productivity* — output per worker-hour, driven by physical capital, human capital, and technology."},{"heading":"Worked example","text":"Real GDP rises from $20.00T to $20.60T. Growth = (20.60 − 20.00) ÷ 20.00 × 100 = 0.60 ÷ 20 × 100 = 3%. At 3% per year, the rule of 70 says output doubles in about 70 ÷ 3 ≈ 23.3 years. If that $21T economy has 300 million people, GDP per capita = 21,000,000,000,000 ÷ 300,000,000 = $70,000 per person."},{"heading":"Your turn","text":"(1) Real GDP goes $50T → $51T; find the growth rate. (2) At 2% growth, roughly how long to double? (3) GDP $6T, population 200 million — find GDP per capita. (4) Two economies grow at 1% and 7%; which doubles roughly seven times faster? Answers: (1) 1 ÷ 50 × 100 = 2%; (2) 70 ÷ 2 = 35 years; (3) 6,000,000,000,000 ÷ 200,000,000 = $30,000; (4) the 7% economy (≈10 years vs ≈70 years)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using nominal GDP for growth, so inflation masquerades as real gains. Mistake: forgetting that total GDP can rise while per-capita GDP falls if population grows faster. Exit: (a) The rule of 70 estimates what? (b) A 5% growth rate doubles output in about how many years? Answers: the time for a quantity to double; about 14 years (70 ÷ 5)."}]}'::jsonb, 'Growth rate = ΔReal GDP ÷ old Real GDP. Rule of 70: doubling time ≈ 70 ÷ growth rate (%).', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In GDP = C + I + G + (X − M), imports are…","options":["added, like consumption","subtracted, because they are produced abroad","ignored entirely","counted twice"],"answer":1,"explanation":"Imports are foreign-produced, so they are subtracted."},{"prompt":"Nominal GDP is $24T and the GDP deflator is 120. Real GDP is…","options":["$28.8T","$24T","$20T","$12T"],"answer":2,"explanation":"24 ÷ (120 ÷ 100) = 24 ÷ 1.20 = $20T."},{"prompt":"An economy has 120 million employed and 30 million unemployed. The unemployment rate is…","options":["25%","20%","30%","15%"],"answer":1,"explanation":"Labor force = 150M; 30 ÷ 150 = 20%."},{"prompt":"The CPI rises from 150 to 156. The inflation rate is…","options":["6%","4%","3%","1.5%"],"answer":1,"explanation":"(156 − 150) ÷ 150 × 100 = 4%."},{"prompt":"At a 4% annual growth rate, output roughly doubles in…","options":["about 4 years","about 17.5 years","about 40 years","about 70 years"],"answer":1,"explanation":"Rule of 70: 70 ÷ 4 ≈ 17.5 years."},{"prompt":"A discouraged worker who stops looking for a job causes the measured unemployment rate to…","options":["rise","fall","stay exactly the same","become negative"],"answer":1,"explanation":"They leave the labor force, so measured unemployment falls."}]}'::jsonb, null, 8),
  (6, 'Money and the banking system', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the functions of money and use the money multiplier to see how banks expand the money supply. Warm-up: name one thing money does that barter cannot do easily."},{"heading":"The idea","text":"Money serves three functions: a *medium of exchange* (accepted for goods), a *store of value* (holds purchasing power over time), and a *unit of account* (a common measuring stick for prices). Economists track it with measures like M1 (cash and checkable deposits) and the broader M2. Under *fractional-reserve banking*, a bank keeps a fraction of deposits as reserves and lends the rest; those loans become new deposits elsewhere, which are lent again. The maximum expansion is the *money multiplier* = 1 ÷ reserve ratio."},{"heading":"Worked example","text":"Reserve ratio = 10% = 0.10, so the money multiplier = 1 ÷ 0.10 = 10. A new $1,000 deposit can support up to $1,000 × 10 = $10,000 of money economy-wide. Trace the first step: the bank keeps 10% of $1,000 = $100 in reserve and lends $900. That $900 is deposited at another bank, which keeps $90 and lends $810, and so on — the geometric series sums to the $10,000 total."},{"heading":"Your turn","text":"(1) Reserve ratio 20% — find the money multiplier. (2) With that multiplier, how much total money can a $500 deposit support? (3) On that first $500 deposit at a 20% ratio, how much does the bank lend? (4) Does a *higher* reserve ratio make the multiplier larger or smaller? Answers: (1) 1 ÷ 0.20 = 5; (2) 500 × 5 = $2,500; (3) it keeps 20% = $100 and lends $400; (4) smaller — more is held back, so less is re-lent."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking banks lend out all deposits (they must hold reserves). Mistake: multiplying by the reserve ratio instead of dividing into 1. Exit: (a) A 25% reserve ratio gives what multiplier? (b) Which function of money lets you compare a $3 coffee and a $30,000 car? Answers: 1 ÷ 0.25 = 4; unit of account."}]}'::jsonb, 'Money multiplier = 1 ÷ reserve ratio. Banks lend out what they don''t hold in reserve.', 13),
  (7, 'Fiscal policy: budgets, deficits, and the multiplier', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell a deficit from a surplus, classify fiscal policy as expansionary or contractionary, and use the spending multiplier. Warm-up: if a government spends more than it collects in taxes, what is the gap called?"},{"heading":"The idea","text":"*Fiscal policy* is the government''s use of spending and taxes. When spending exceeds tax revenue there is a *budget deficit*; when revenue exceeds spending, a *surplus*. In a downturn, *expansionary* policy (more spending or lower taxes) boosts aggregate demand; in a boom, *contractionary* policy cools it. Spending has an amplified effect because each dollar is re-spent: the *spending multiplier* = 1 ÷ (1 − MPC), where MPC is the marginal propensity to consume — the fraction of each extra dollar of income that households spend."},{"heading":"Worked example","text":"A government spends $6.0T and collects $5.5T in taxes. Budget balance = 5.5 − 6.0 = −$0.5T, a $0.5T deficit. Now suppose MPC = 0.8, so the multiplier = 1 ÷ (1 − 0.8) = 1 ÷ 0.2 = 5. A $100B increase in government purchases can raise real GDP by up to 100 × 5 = $500B, because the initial spending becomes income that is partly re-spent, round after round."},{"heading":"Your turn","text":"(1) Spending $4T, taxes $4.3T — deficit or surplus, and how much? (2) MPC = 0.75 — find the spending multiplier. (3) With that multiplier, what is the maximum GDP effect of a $50B spending rise? (4) To fight a recession, should a government use expansionary or contractionary policy? Answers: (1) surplus of $0.3T (4.3 − 4.0); (2) 1 ÷ (1 − 0.75) = 1 ÷ 0.25 = 4; (3) 50 × 4 = $200B; (4) expansionary."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing the *deficit* (a one-year gap) with the *debt* (the accumulated total of past deficits). Mistake: using (1 − MPC) as the multiplier instead of 1 ÷ (1 − MPC). Exit: (a) If MPC = 0.9, what is the multiplier? (b) Lower taxes in a slump is which kind of policy? Answers: 1 ÷ (1 − 0.9) = 10; expansionary."}]}'::jsonb, 'Deficit = spending − revenue. Spending multiplier = 1 ÷ (1 − MPC).', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"gross domestic product (GDP)","translation":"the market value of all final goods and services produced within a country in a period","example":"Adding C, I, G, and net exports gives GDP."},{"term":"unemployment rate","translation":"the share of the labor force that is without a job and actively looking for one","example":"Ten million unemployed in a 160-million labor force is a 6.25% unemployment rate."},{"term":"inflation","translation":"a sustained rise in the general price level, measured with a price index like the CPI","example":"A CPI move from 200 to 210 is 5% inflation."},{"term":"aggregate demand","translation":"total spending on an economy''s output at each price level; it slopes downward","example":"Expansionary policy shifts aggregate demand to the right."},{"term":"monetary policy","translation":"the central bank''s management of the money supply and interest rates to steer the economy","example":"Cutting the policy interest rate is expansionary monetary policy."},{"term":"fiscal policy","translation":"the government''s use of spending and taxation to influence the economy","example":"Raising spending in a recession is expansionary fiscal policy."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"With a reserve ratio of 25%, the money multiplier is…","options":["25","4","0.25","10"],"answer":1,"explanation":"1 ÷ 0.25 = 4."},{"prompt":"A new $1,000 deposit with a 10% reserve ratio can support total money up to…","options":["$1,100","$9,000","$10,000","$100,000"],"answer":2,"explanation":"1,000 × (1 ÷ 0.10) = $10,000."},{"prompt":"If MPC = 0.8, the spending multiplier is…","options":["0.2","1.25","5","8"],"answer":2,"explanation":"1 ÷ (1 − 0.8) = 1 ÷ 0.2 = 5."},{"prompt":"A government spending $5T and collecting $4T in taxes has a…","options":["$1T surplus","$1T deficit","balanced budget","$9T deficit"],"answer":1,"explanation":"Spending exceeds revenue by $1T — a deficit."},{"prompt":"The aggregate demand curve slopes downward, meaning a lower price level is associated with…","options":["less real output demanded","more real output demanded","no change in output","higher unemployment always"],"answer":1,"explanation":"Lower price level, greater quantity of real GDP demanded."},{"prompt":"Lowering the central bank''s policy interest rate is an example of…","options":["contractionary fiscal policy","expansionary monetary policy","a balanced budget","raising the reserve ratio"],"answer":1,"explanation":"Cheaper credit spurs borrowing and spending — expansionary monetary policy."}]}'::jsonb, null, 8),
  (10, 'Applied project: an economic-conditions briefing', 'writing', '{"sections":[{"heading":"The task","text":"Write a one-page briefing on a hypothetical (or real, if you have data) economy and recommend a policy response. You are the analyst; keep every number defined and every claim tied to a mechanism from this course."},{"heading":"Milestones","text":"1) Report real GDP and its growth rate, and compute GDP per capita from a population you state. 2) Report the unemployment rate and the inflation rate, each with the formula you used. 3) Diagnose the economy: is it in a slump (high unemployment) or overheating (high inflation)? 4) Recommend one fiscal and one monetary action, saying whether each is expansionary or contractionary and how it shifts aggregate demand."},{"heading":"Self-check rubric","text":"✔ Every rate is computed, not asserted (show unemployed ÷ labor force, ΔCPI ÷ CPI, ΔGDP ÷ GDP). ✔ Your diagnosis matches your numbers. ✔ Your fiscal and monetary recommendations point the same direction as the diagnosis (expansionary for a slump, contractionary for overheating). ✔ You distinguish a deficit from the debt, and nominal from real GDP. If all four hold, you''ve reasoned like a macroeconomist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000006' and l.position = v.pos
);
